def CanyonSearch (a : Array Int) (b : Array Int) (h_precond : CanyonSearch_precond (a) (b)) : Nat :=
  let a_list := a.toList
  let b_list := b.toList
  let min_diff :=
    a_list.foldl (fun acc ai =>
      b_list.foldl (fun acc_bi bi =>
        let diff := (ai - bi).natAbs
        if diff < acc then diff else acc
      ) 4294967296 -- Initialize with a value larger than any possible Int difference
    ) 4294967296
  min_diff
